package dev.hossain.highlight.build

/**
 * Emits a single Kotlin source file containing the precompiled SpanStyle maps for the
 * four bundled hljs themes.
 *
 * The output file is checked in nowhere - it lives under
 * `compose-highlight/build/generated/source/themes/main/`, is added to the main Kotlin source
 * set by the Gradle task, and is regenerated whenever the source CSS files change.
 *
 * Format goals:
 * - Plain `mapOf(...)` literals - debuggable, readable in IDE, easy to diff.
 * - Source-order preserved (CssThemeParser uses LinkedHashMap), so the generated file diffs
 *   match CSS ordering.
 * - Uses `Color(0xAARRGGBB)` constructor everywhere - same form as the rest of the codebase.
 */
internal object ThemeSourceEmitter {
    /**
     * Renders the full Kotlin source for the GeneratedThemes object.
     *
     * @param themes Map of constant name (e.g. `"TOMORROW"`) → parsed entries + asset path used
     *   to compute the matching content identity.
     */
    fun emit(themes: List<ThemeBuildInput>): String {
        val sb = StringBuilder()
        sb.appendLine("// Generated by GenerateThemesTask. DO NOT EDIT.")
        sb.appendLine("// Source CSS: src/main/assets/compose-highlight/themes/")
        sb.appendLine()
        sb.appendLine("@file:Suppress(\"ktlint\", \"detekt:all\", \"RedundantSuppression\")")
        sb.appendLine()
        sb.appendLine("package dev.hossain.highlight.engine")
        sb.appendLine()
        sb.appendLine("import androidx.compose.ui.graphics.Color")
        sb.appendLine("import androidx.compose.ui.text.SpanStyle")
        sb.appendLine("import androidx.compose.ui.text.font.FontStyle")
        sb.appendLine("import androidx.compose.ui.text.font.FontWeight")
        sb.appendLine()
        sb.appendLine("/**")
        sb.appendLine(" * Precompiled color maps for the four bundled hljs themes.")
        sb.appendLine(" *")
        sb.appendLine(" * Generated at build time from the CSS files in")
        sb.appendLine(" * `src/main/assets/compose-highlight/themes/` so the runtime ThemeParser is never")
        sb.appendLine(" * invoked for built-in themes. The generator uses logic that mirrors the runtime")
        sb.appendLine(" * parser; a parity test (`GeneratedThemesParityTest`) verifies the two stay in")
        sb.appendLine(" * sync.")
        sb.appendLine(" */")
        sb.appendLine("internal object GeneratedThemes {")
        themes.forEachIndexed { index, theme ->
            if (index > 0) sb.appendLine()
            emitTheme(sb, theme)
        }
        sb.appendLine("}")
        return sb.toString()
    }

    private fun emitTheme(sb: StringBuilder, theme: ThemeBuildInput) {
        sb.appendLine("    /** Identity hash for the [${theme.constantName}] color map (matches `contentDigest64(\"asset\", \"${theme.assetPath}\")`). */")
        sb.appendLine("    const val ${theme.constantName}_IDENTITY: Long = ${theme.contentIdentity}L")
        sb.appendLine()
        sb.appendLine("    /** Color map for the bundled `${theme.assetPath}` theme. */")
        sb.appendLine("    val ${theme.constantName}: Map<String, SpanStyle> = mapOf(")
        for ((selector, style) in theme.entries) {
            sb.append("        ").append(quoteString(selector)).append(" to ").append(emitSpanStyle(style)).appendLine(",")
        }
        sb.appendLine("    )")
    }

    private fun emitSpanStyle(style: ParsedStyle): String {
        val parts = mutableListOf<String>()
        if (style.color != null) parts.add("color = ${emitColor(style.color)}")
        if (style.fontWeight != null) {
            val ref = when (style.fontWeight) {
                ParsedFontWeight.Bold -> "FontWeight.Bold"
                ParsedFontWeight.Normal -> "FontWeight.Normal"
            }
            parts.add("fontWeight = $ref")
        }
        if (style.fontStyleItalic == true) parts.add("fontStyle = FontStyle.Italic")
        if (style.background != null) parts.add("background = ${emitColor(style.background)}")
        return "SpanStyle(${parts.joinToString(", ")})"
    }

    private fun emitColor(argb: Long): String {
        // 0xAARRGGBB - same form used by the rest of the codebase.
        // The literal is unsigned (Long) because Color(Long) takes ARGB packed in the low 32 bits.
        return "Color(0x${"%08X".format(argb)})"
    }

    private fun quoteString(s: String): String {
        val escaped = s
            .replace("\\", "\\\\")
            .replace("\"", "\\\"")
            .replace("\$", "\\\$")
        return "\"$escaped\""
    }
}

/** Inputs the codegen task hands to [ThemeSourceEmitter]. */
internal data class ThemeBuildInput(
    /** Kotlin constant name in `GeneratedThemes`, e.g. `"TOMORROW"`. */
    val constantName: String,
    /** Asset path the runtime would have loaded - used to compute matching identity hash. */
    val assetPath: String,
    /** SHA-256-derived identity hash of [assetPath], 64-bit. */
    val contentIdentity: Long,
    /** Parsed entries in CSS source order. */
    val entries: List<Pair<String, ParsedStyle>>,
)
